def pancake_sort(nums):
    def flip(arr, k):
        arr[:k] = arr[:k][::-1]
        return arr

    n = len(nums)
    for size in range(n, 1, -1):
        max_idx = 0
        for i in range(size):
            if nums[i] > nums[max_idx]:
                max_idx = i
        if max_idx != size - 1:
            if max_idx != 0:
                flip(nums, max_idx + 1)
            flip(nums, size)
    return nums
```

