    def sum_proper_divisors(n):
        if n < 2:
            return 0
        total = 1
        i = 2
        while i * i <= n:
            if n % i == 0:
                total += i
                if i != n // i:
                    total += n // i
            i += 1
        return total

    total_sum = 0
    for a in range(1, limit + 1):
